import com.rabbitmq.client.Channel;
import com.rabbitmq.client.Connection;
import com.rabbitmq.client.ConnectionFactory;
import java.util.HashMap;
import java.util.Map;

public class QuorumQueueDeclaration {
    public static void main(String[] args) throws Exception {
        ConnectionFactory factory = new ConnectionFactory();
        factory.setHost("localhost");

        try (Connection connection = factory.newConnection();
             Channel channel = connection.createChannel()) {

            Map<String, Object> argsMap = new HashMap<>();
            // Explicitly declare the queue type as quorum
            argsMap.put("x-queue-type", "quorum");
            // Optional: Configure delivery limit for poison pill protection
            argsMap.put("x-delivery-limit", 5);

            channel.queueDeclare("order.processing.quorum", true, false, false, argsMap);

            System.out.println("Quorum queue declared successfully with Raft consensus.");
        }
    }
}
